using System.Text.Json;

namespace Gojo.Experiments.ConstructionMachines;

/// <summary>Offline presentation only. All geometry and topology come from retained reads.</summary>
public static class JointReview
{
    public static void Write(string path, string json)
    {
        using var parsed = JsonDocument.Parse(json);
        File.WriteAllText(path, Template.Replace("__DATA__", JsonSerializer.Serialize(parsed.RootElement), StringComparison.Ordinal));
    }
    private const string Template = """
