:root{color-scheme:light;--ink:#263f43;--muted:#687a7b;--edge:#d8e2de;--accent:#246d64;--paper:#f2f5f0;--pink:#b5597b}*{box-sizing:border-box}
body{margin:0;background:var(--paper);color:var(--ink);font:15px/1.5 system-ui,sans-serif}main{max-width:1450px;margin:auto;padding:20px 24px}h1{font-size:29px;font-weight:550;letter-spacing:-.03em;margin:0}h2{font-size:19px;font-weight:600;margin:0}h3{font-size:14px;margin:0 0 6px}p{margin:5px 0}header{display:flex;align-items:baseline;justify-content:space-between;margin-bottom:13px}small,.muted{color:var(--muted)}button,select,input{font:inherit;accent-color:var(--accent)}button,select{border:1px solid var(--edge);background:white;color:var(--ink);border-radius:8px;padding:7px 11px}button,select,summary{cursor:pointer}button:disabled{opacity:.4;cursor:default}button:focus-visible,select:focus-visible,input:focus-visible,a:focus-visible{outline:3px solid #d9ac4b;outline-offset:2px}.primary{background:var(--accent);color:white}.controls,.card{background:white;border:1px solid var(--edge);border-radius:12px}.controls{padding:10px 12px;margin-bottom:13px}.row{display:flex;gap:8px;align-items:center}.row select{flex:1;min-width:0;font-weight:550}.row+.row{border-top:1px solid #edf1ed;margin-top:8px;padding-top:9px}.row input[type=range]{flex:1;min-width:70px}.counter{font-size:12px;min-width:115px;text-align:center}.checks{display:flex;gap:12px;color:var(--muted);font-size:12px;white-space:nowrap}.checks label{display:flex;gap:4px;align-items:center}.workspace{display:grid;grid-template-columns:minmax(0,1fr) 370px;gap:15px;align-items:start}.drawing-head{padding:14px 17px 8px}.drawing-head p{font-size:13px;color:var(--muted);max-width:800px}.figure{height:clamp(330px,53vh,600px);padding:8px 18px}.figure svg{width:100%;height:100%;display:block}.legend{display:flex;gap:17px;flex-wrap:wrap;border-top:1px solid #edf1ed;padding:10px 17px;font-size:12px;color:var(--muted)}.legend span{display:flex;align-items:center;gap:6px}.swatch{display:inline-block;width:18px;border-top:2px solid}.swatch.dash{border-top-style:dashed}.stats{display:grid;grid-template-columns:repeat(6,1fr);gap:8px;margin-top:13px}.stat{padding:9px 10px;background:#fff;border:1px solid var(--edge);border-radius:9px}.stat span{display:block;font-size:11px;color:var(--muted)}.stat strong{display:block;font-size:22px;font-weight:500;font-variant-numeric:tabular-nums}.rail{display:grid;gap:13px}.panel{padding:13px 15px}.graph{height:230px;margin:4px -7px}.graph svg{width:100%;height:100%;display:block}.graph-note{font-size:12px;color:var(--muted)}.phase{display:inline-block;color:var(--accent);font-size:12px;font-weight:650;margin-bottom:5px}.phase.change{color:#9e6721}.caption{font-size:14px}.event-list{font-size:12px;color:var(--muted);padding-left:18px;max-height:240px;overflow:auto}.event-list li+li{margin-top:7px}.notes{font-size:13px;color:var(--muted);padding-left:19px;margin:5px 0}.notes li+li{margin-top:7px}.footer{display:flex;flex-wrap:wrap;gap:16px;border-top:1px solid var(--edge);padding-top:14px;margin-top:17px;font-size:12px}.footer a{color:var(--accent)}details{margin-top:13px;font-size:13px;color:var(--muted)}details summary{color:var(--ink);width:fit-content}details p,details ul{max-width:1000px}.kbd{margin-left:auto}.ink{fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-width:3;vector-effect:non-scaling-stroke}.target{stroke:var(--pink);stroke-dasharray:5 5;stroke-width:1.8;opacity:.65}.initial{stroke:#b9c5c1;stroke-width:1.4;opacity:.65}.retired{stroke:#ba8536;stroke-dasharray:3 4;stroke-width:2;opacity:.85}.site{fill:white;stroke-width:1.6;vector-effect:non-scaling-stroke}.label{font:12px system-ui;fill:#486468;paint-order:stroke;stroke:white;stroke-width:3px}.graph-label{font:13px system-ui;fill:#486468}.badge{font:11px system-ui;fill:#9e6721;paint-order:stroke;stroke:white;stroke-width:3px}
@media(max-width:1050px){.workspace{grid-template-columns:minmax(0,1fr) 320px}.checks{flex-basis:100%;justify-content:flex-end}.row+.row{flex-wrap:wrap}.counter{min-width:100px}.figure{height:49vh}.stats{grid-template-columns:repeat(3,1fr)}}
@media(max-width:750px){main{padding:14px 11px}header small{display:none}h1{font-size:24px}.workspace{grid-template-columns:1fr}.figure{height:43vh;min-height:300px}.rail{grid-template-columns:1fr 1fr}.rail .panel:first-child{grid-column:1/-1}.rail .panel:nth-child(2){grid-column:1/-1}.graph{height:220px}.row select{font-size:13px}.checks{justify-content:flex-start;gap:9px;font-size:11px}.stats{gap:6px}.stat{padding:8px}.stat strong{font-size:20px}.kbd{display:none}.drawing-head{padding:12px}.legend{padding:10px 12px;gap:10px}.event-list{max-height:200px}}
@media(max-width:430px){.rail{grid-template-columns:1fr}.counter{min-width:80px;font-size:11px}.row button{padding:6px 9px}.figure{padding:5px 10px}.checks{white-space:normal}.graph{height:210px}}
</style></head><body><main>
<header><h1>Joints that change construction</h1><small>Gojo · saved native experiments</small></header>
<section class="controls" aria-label="Experiment controls"><div class="row"><button id="prevCase" aria-label="Previous experiment">‹</button><select id="case" aria-label="Experiment"></select><button id="nextCase" aria-label="Next experiment">›</button></div>
<div class="row"><button id="prev" aria-label="Previous observation">←</button><button id="play" class="primary">Play</button><button id="next" aria-label="Next observation">→</button><span id="counter" class="counter"></span><input id="frame" type="range" min="0" value="0" aria-label="Observation"><div class="checks"><label><input id="targets" type="checkbox" checked> Targets</label><label><input id="ghosts" type="checkbox"> Starting drawing</label><label><input id="sites" type="checkbox" checked> Sites</label></div></div></section>
<div class="workspace"><section><div class="card"><div class="drawing-head"><h2 id="title"></h2><p id="description"></p></div><div id="drawing" class="figure"></div><div class="legend"><span><i class="swatch" style="border-color:#347d92"></i>Current branches</span><span><i class="swatch dash" style="border-color:#b5597b"></i>Requested geometry</span><span><i class="swatch" style="border-color:#b9c5c1"></i>Starting drawing</span><span><i class="swatch dash" style="border-color:#ba8536"></i>Retired this frame</span></div></div><div id="stats" class="stats"></div></section>
<aside class="rail"><section class="card panel"><h3>Branch connections</h3><div id="graph" class="graph"></div><p class="graph-note">Schematic of drawn-branch incidence. Coincident positions can remain separate. Colours distinguish branch groups; shared parameters can still coordinate their movement.</p></section><section class="card panel"><span id="phase" class="phase"></span><p id="caption" class="caption"></p><details id="receiptDetails"><summary>Requests and change evidence</summary><ul id="events" class="event-list"></ul></details></section><section class="card panel"><h3>What to look for</h3><ul id="notes" class="notes"></ul></section></aside></div>
<details><summary>How to read this experiment</summary><p>Targets and starting drawings are authored interpretations. Coordinate agreement and connectivity are different reads. The page plays retained observations; construction changes are authored proposals, not predictions by a trained model.</p><ul id="summary"></ul></details>
