</main><script id="data" type="application/json">__DATA__</script><script>
'use strict';
const data=JSON.parse(document.getElementById('data').textContent),$=id=>document.getElementById(id),NS='http://www.w3.org/2000/svg';
let caseIndex=0,frameIndex=0,timer=null;const colours=['#347d92','#43855e','#9b6d9c','#b58c40'];
function el(tag,attrs={},text){const e=document.createElementNS(NS,tag);for(const[k,v]of Object.entries(attrs))e.setAttribute(k,v);if(text!==undefined)e.textContent=text;return e}
function html(tag,cls,text){const e=document.createElement(tag);if(cls)e.className=cls;if(text!==undefined)e.textContent=text;return e}
function current(){return data.scenarios[caseIndex]}function frame(){return current().frames[frameIndex]}
function groups(g){const remaining=new Set(g.nodes.map(n=>n.id)),result=[];while(remaining.size){const first=remaining.values().next().value,q=[first],part=[];remaining.delete(first);while(q.length){const id=q.shift();part.push(g.nodes.find(n=>n.id===id));for(const e of g.edges){const other=e.from===id?e.to:e.to===id?e.from:null;if(other&&remaining.delete(other))q.push(other)}}result.push(part)}return result}
function tooltip(e,text){e.append(el('title',{},text));return e}
function edge(svg,e,positions,cls,colour){const a=positions.get(e.from),b=positions.get(e.to);svg.append(tooltip(el('line',{x1:a[0],y1:a[1],x2:b[0],y2:b[1],class:'ink '+cls,stroke:colour??'#347d92'}),`${e.id}: ${e.from} → ${e.to}`))}
function drawing(){const s=current(),f=frame(),all=[s.initial,s.target,...s.frames.map(x=>x.geometry)].flatMap(g=>g.nodes.map(n=>n.point)),xs=all.map(p=>p[0]),ys=all.map(p=>p[1]);const box=[Math.min(...xs)-28,-Math.max(...ys)-28,Math.max(...xs)-Math.min(...xs)+56,Math.max(...ys)-Math.min(...ys)+56];const svg=el('svg',{viewBox:box.join(' '),role:'img','aria-label':'Current joint drawing with target and site observations'});const pos=g=>new Map(g.nodes.map(n=>[n.id,[n.point[0],-n.point[1]]]));
if($('ghosts').checked)for(const e of s.initial.edges)edge(svg,e,pos(s.initial),'initial');if($('targets').checked)for(const e of s.target.edges)edge(svg,e,pos(s.target),'target');
if(f.phase==='Reinterpretation'&&frameIndex>0){const old=s.frames[frameIndex-1].geometry;for(const e of old.edges)if(!f.geometry.edges.some(n=>n.id===e.id))edge(svg,e,pos(old),'retired')}
const palette=new Map();groups(f.geometry).forEach((g,i)=>g.forEach(n=>palette.set(n.id,n.degree?colours[i%colours.length]:'#a3aeaa')));const positions=pos(f.geometry);for(const e of f.geometry.edges)edge(svg,e,positions,'',palette.get(e.from));
if($('sites').checked){const at=new Map();for(const n of f.geometry.nodes){const key=n.point.join(',');if(!at.has(key))at.set(key,[]);at.get(key).push(n)}for(const nodes of at.values()){const n=nodes[0],[x,y]=positions.get(n.id);const text=nodes.map(v=>`${v.label}: degree ${v.degree}${v.external.length?'; ports '+v.external.map(i=>'P'+i).join(', '):''}`).join('\n');svg.append(tooltip(el('circle',{cx:x,cy:y,r:2.7,class:'site',stroke:palette.get(n.id)}),text));if(nodes.length>1)svg.append(el('text',{x:x+5,y:y-6,class:'badge'},nodes.length+' distinct sites'));else if(n.external.length||n.degree===0)svg.append(el('text',{x:x+5,y:y-6,class:'label'},n.degree===0?'remembered':n.external.map(i=>'P'+i).join('/')))}}
$('drawing').replaceChildren(svg)}
function graph(){const g=frame().geometry,parts=groups(g),svg=el('svg',{viewBox:'0 0 500 260',role:'img','aria-label':'Schematic node and edge incidence'}),positions=new Map();parts.forEach((part,i)=>{const cx=(i+.5)*500/parts.length,cy=125,root=[...part].sort((a,b)=>b.degree-a.degree)[0];positions.set(root.id,[cx,cy]);const rest=part.filter(n=>n!==root),r=Math.min(87,205/parts.length);rest.forEach((n,j)=>{const angle=-Math.PI/2+j*2*Math.PI/rest.length;positions.set(n.id,[cx+r*Math.cos(angle),cy+r*Math.sin(angle)])});const colour=root.degree?colours[i%colours.length]:'#a3aeaa';for(const e of g.edges.filter(e=>part.some(n=>n.id===e.from)))edge(svg,e,positions,'',colour);for(const n of part){const[x,y]=positions.get(n.id);svg.append(tooltip(el('circle',{cx:x,cy:y,r:6,fill:'white',stroke:colour,'stroke-width':2}),`${n.label}; ${n.degree} branches; ports ${n.external.join(', ')||'internal'}`));svg.append(el('text',{x:x+9,y:y-8,class:'graph-label'},n.external.length?n.external.map(i=>'P'+i).join('/'):n.id))}svg.append(el('text',{x:cx,y:247,'text-anchor':'middle',class:'graph-label'},root.degree?'Connected group '+(i+1):'Remembered site'))});$('graph').replaceChildren(svg)}
function render(){const s=current(),f=frame();$('case').value=caseIndex;$('title').textContent=s.title;$('description').textContent=s.description;$('frame').max=s.frames.length-1;$('frame').value=frameIndex;$('counter').textContent=`Pass ${f.round} · ${frameIndex+1}/${s.frames.length}`;$('phase').textContent=f.phase;$('phase').className='phase'+(f.phase==='Reinterpretation'?' change':'');$('caption').textContent=f.caption;$('prev').disabled=frameIndex===0;$('next').disabled=frameIndex===s.frames.length-1;$('prevCase').disabled=caseIndex===0;$('nextCase').disabled=caseIndex===data.scenarios.length-1;
$('notes').replaceChildren(...s.lookFor.map(x=>html('li','',x)));$('events').replaceChildren(...(f.events.length?f.events:['No numeric response or rewrite evidence at this observation.']).map(x=>html('li','',x)));$('receiptDetails').open=f.phase==='Reinterpretation';
$('stats').replaceChildren(...[['gap','Position gap'],['movement','Largest move'],['sites','Sites'],['branches','Branches'],['groups','Groups'],['openPaths','Unresolved paths']].map(([k,label])=>{const e=html('div','stat');e.append(html('span','',label),html('strong','',String(f.stats[k])));return e}));drawing();graph();history.replaceState(null,'',`#${encodeURIComponent(s.id)}/${frameIndex}`)}
function stop(){if(timer)clearInterval(timer);timer=null;$('play').textContent='Play'}function move(delta){stop();frameIndex=Math.max(0,Math.min(current().frames.length-1,frameIndex+delta));render()}function changeCase(delta){stop();caseIndex=Math.max(0,Math.min(data.scenarios.length-1,caseIndex+delta));frameIndex=0;render()}
function readHash(){const p=location.hash.slice(1).split('/');let id='';try{id=decodeURIComponent(p[0]??'')}catch{}const at=data.scenarios.findIndex(s=>s.id===id);if(at>=0)caseIndex=at;frameIndex=Math.max(0,Math.min(current().frames.length-1,Number(p[1])||0))}
data.scenarios.forEach((s,i)=>{const e=html('option','',`${i+1}. ${s.title}`);e.value=i;$('case').append(e)});$('summary').replaceChildren(...data.summary.map(x=>html('li','',x)));
$('prev').onclick=()=>move(-1);$('next').onclick=()=>move(1);$('prevCase').onclick=()=>changeCase(-1);$('nextCase').onclick=()=>changeCase(1);$('case').onchange=()=>{stop();caseIndex=Number($('case').value);frameIndex=0;render()};$('frame').oninput=()=>{stop();frameIndex=Number($('frame').value);render()};for(const id of ['targets','ghosts','sites'])$(id).onchange=render;
$('play').onclick=()=>{if(timer){stop();return}if(frameIndex===current().frames.length-1)frameIndex=0;render();$('play').textContent='Pause';timer=setInterval(()=>{if(frameIndex>=current().frames.length-1){stop();return}frameIndex++;render()},850)};
document.addEventListener('keydown',e=>{if(/INPUT|SELECT|TEXTAREA/.test(e.target.tagName))return;if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();const d=e.key==='ArrowLeft'?-1:1;e.shiftKey?changeCase(d):move(d)}else if(e.code==='Space'){e.preventDefault();$('play').click()}});window.addEventListener('hashchange',()=>{stop();readHash();render()});readHash();render();
</script></body></html>
""";
}
